import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a static card label node for "Collection 3".
 * Applies a textured plane with a headline text overlay.
 */
export default function createNode(config, ctx) {
  const { textureLoader, fontAtlas, THREE } = ctx;

  // --- Container group ---
  const group = new THREE.Group();

  // --- Plane geometry (size derived from texture aspect ratio) ---
  // Base width in scene units; height will be set from texture ratio later if possible.
  const BASE_WIDTH = 1.8;
  const planeGeom = new THREE.PlaneGeometry(BASE_WIDTH, BASE_WIDTH * (320 / 512)); // placeholder ratio
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10', // surface color as placeholder
    transparent: true,
  });
  const planeMesh = new THREE.Mesh(planeGeom, material);
  group.add(planeMesh);

  // --- Load texture ---
  textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = 'srgb';
    // Update geometry aspect to match texture
    const aspect = tex.image.width / tex.image.height;
    const height = BASE_WIDTH / aspect;
    planeGeom.dispose();
    const newGeom = new THREE.PlaneGeometry(BASE_WIDTH, height);
    planeMesh.geometry = newGeom;
    // Store in cleanup
    group.userData._planeGeom = newGeom;

    material.map = tex;
    material.needsUpdate = true;
  }).catch(() => {
    // fallback: keep placeholder
  });

  // --- Text: "Collection 3" ---
  const textObj = fontAtlas.createText('Collection 3', {
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 300, // prevent overflow
  });
  // Position at bottom-center of card, with small padding
  textObj.position.set(0, -0.55, 0.01); // slightly in front of plane
  textObj.scale.set(0.001, 0.001, 0.001); // adjust scale if needed (atlas text can be large)
  group.add(textObj);

  // --- Fallback scale for text (if fontAtlas size is huge) ---
  // Typically createText returns 1px = 1 scene unit, so we scale down.
  // We'll apply a uniform scale of 0.008 to bring it to ~0.3 scene units (based on 39px at default camera distance)
  textObj.scale.setScalar(0.008);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    planeGeom.dispose();
    if (group.userData._planeGeom) group.userData._planeGeom.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No timelines to kill
  };

  // Store planeGeom reference for disposal
  group.userData._planeGeom = planeGeom;

  return group;
}
